head.script:
    scwin.tabCnt = 0;
    scwin.onpageload = function() {
        tab1_textbox1.setValue("AAAA");
        tab1_textbox2.setValue("BBBB");
    };
    scwin.onpageunload = function() {

    };
    scwin.trigger1_onclick = function() {
        scwin.tabCnt++;
        var tabId = "tab_dynamic_" + scwin.tabCnt;
        var src = "WAEA_21_tabControl.xml";
        var tabOpt = {
            label: "pf" + scwin.tabCnt,
            closable: true
        };
        var contOpt = {
            frameMode: "wframe",
            src: src,
            alwaysDraw: false
        };
        tabControl1.addTab(tabId, tabOpt, contOpt);
    };

	scwin.checkVal = function() {
		const temp = WebSquare.logger.getLog();
		return temp.indexOf("Cannot set properties of null") == -1;
	}
	scwin.unitTest = function(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_tab_dynamic_1').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
